package com.askrueger.radartren.domain

data class Station(val id: String, val name: String, val latitude: Double, val longitude: Double)

data class LongDistanceTrain(val product: String, val originId: String, val destinationId: String)

data class Line(val routeId: String, val name: String, val color: String)

/** Station, line and train names from Renfe's static GTFS, generated by tools/generate_catalog.py. */
class StaticCatalog(
    private val stations: Map<String, Station>,
    private val lines: Map<String, Line>,
    private val trains: Map<String, LongDistanceTrain>,
) {
    fun station(id: String): Station? = stations[id.trim()]
    fun line(routeId: String): Line? = lines[routeId.trim()]
    fun train(number: String): LongDistanceTrain? = trains[number]

    companion object {
        val EMPTY = StaticCatalog(emptyMap(), emptyMap(), emptyMap())

        fun parse(stations: Sequence<String>, lines: Sequence<String>, trains: Sequence<String>) = StaticCatalog(
            stations = rows(stations).associate { c ->
                c[0] to Station(c[0], c[1], c[2].toDouble(), c[3].toDouble())
            },
            lines = rows(lines).associate { c -> c[0] to Line(c[0], c[1], c[2]) },
            trains = rows(trains).associate { c -> c[0] to LongDistanceTrain(c[1], c[2], c[3]) },
        )

        private fun rows(lines: Sequence<String>) = lines.drop(1).filter(String::isNotBlank).map { it.split(';') }
    }
}
